1	import { serve } from "https://deno.land/std@0.168.0/http/server.ts";
2	import { createClient } from "https://esm.sh/@supabase/supabase-js@2.49.2";
3	import { corsHeaders, handlePreflight } from "../_shared/cors.ts";
4	
5	serve(async (req) => {
6	  const cors = corsHeaders(req);
7	
8	  const preflight = handlePreflight(req);
9	  if (preflight) return preflight;
10	
11	  try {
12	    const SUPABASE_URL = Deno.env.get("SUPABASE_URL")!;
13	    const SUPABASE_SERVICE_ROLE_KEY = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!;
14	    const anonKey = Deno.env.get("SUPABASE_ANON_KEY")!;
15	
16	    const authHeader = req.headers.get("Authorization");
17	    if (!authHeader?.startsWith("Bearer ")) throw new Error("No auth");
18	
19	    const supabaseUser = createClient(SUPABASE_URL, anonKey, {
20	      global: { headers: { Authorization: authHeader } },
21	    });
22	    const token = authHeader.replace("Bearer ", "");
23	    const { data: claimsData, error: claimsError } = await supabaseUser.auth.getClaims(token);
24	    if (claimsError || !claimsData?.claims) throw new Error("Unauthorized");
25	    const userId = claimsData.claims.sub as string;
26	
27	    const supabase = createClient(SUPABASE_URL, SUPABASE_SERVICE_ROLE_KEY);
28	
29	    const { data: roles } = await supabase.from("user_roles").select("role").eq("user_id", userId);
30	    if (!roles?.some((r: any) => r.role === "admin")) {
31	      return new Response(JSON.stringify({ error: "Admin access required" }), {
32	        status: 403, headers: { ...cors, "Content-Type": "application/json" },
33	      });
34	    }
35	
36	    // Parse optional date range from request body
37	    let rangeDays = 30;
38	    let rangeFrom: string | null = null;
39	    let rangeTo: string | null = null;
40	    try {
41	      const text = await req.text();
42	      if (text) {
43	        const body = JSON.parse(text);
44	        if (body.from) rangeFrom = body.from;
45	        if (body.to) rangeTo = body.to;
46	        if (body.days && typeof body.days === "number") rangeDays = Math.min(body.days, 365);
47	      }
48	    } catch { /* empty body = default 30 days */ }
49	
50	    // Validate date inputs
51	    if (rangeFrom && isNaN(Date.parse(rangeFrom))) {
52	      return new Response(JSON.stringify({ error: "Invalid 'from' date format" }), {
53	        status: 400, headers: { ...cors, "Content-Type": "application/json" },
54	      });
55	    }
56	    if (rangeTo && isNaN(Date.parse(rangeTo))) {
57	      return new Response(JSON.stringify({ error: "Invalid 'to' date format" }), {
58	        status: 400, headers: { ...cors, "Content-Type": "application/json" },
59	      });
60	    }
61	
62	    const now = Date.now();
63	    const rangeStartDate = rangeFrom
64	      ? new Date(rangeFrom)
65	      : new Date(now - rangeDays * 24 * 60 * 60 * 1000);
66	    const rangeEndDate = rangeTo ? new Date(rangeTo) : new Date(now);
67	    // Ensure end date includes full day
68	    rangeEndDate.setHours(23, 59, 59, 999);
69	
70	    const rangeStartISO = rangeStartDate.toISOString();
71	    const rangeEndISO = rangeEndDate.toISOString();
72	    const sevenDaysAgo = new Date(now - 7 * 24 * 60 * 60 * 1000).toISOString();
73	    const todayStart = new Date(new Date().setHours(0, 0, 0, 0)).toISOString();
74	    const weekStart = new Date(now - 7 * 24 * 60 * 60 * 1000).toISOString();
75	    const thirtyDaysAgo = new Date(now - 30 * 24 * 60 * 60 * 1000).toISOString();
76	
77	    const [
78	      usersRes, jobsRes, resumesRes, creditsRes,
79	      dailyUsageRes, dailyJobsRes,
80	      paidPaymentsAllRes, paidPaymentsRangeRes,
81	      profilesRes,
82	      usage7dRes, usage30dRes,
83	      resumesTodayRes, resumesWeekRes, resumesMonthRes,
84	    ] = await Promise.all([
85	      supabase.auth.admin.listUsers({ perPage: 1000 }),
86	      supabase.from("jobs").select("id", { count: "exact", head: true }),
87	      supabase.from("resumes").select("id", { count: "exact", head: true }),
88	      supabase.from("usage_logs").select("credits_used"),
89	      supabase.from("usage_logs").select("credits_used, created_at, user_id").gte("created_at", rangeStartISO).lte("created_at", rangeEndISO),
90	      supabase.from("jobs").select("created_at").gte("created_at", rangeStartISO).lte("created_at", rangeEndISO),
91	      // Revenue: all paid payments
92	      supabase.from("payments").select("amount, currency").eq("status", "paid"),
93	      // Revenue: range paid payments with daily breakdown
94	      supabase.from("payments").select("amount, currency, created_at").eq("status", "paid").gte("created_at", rangeStartISO).lte("created_at", rangeEndISO),
95	      // Profiles for conversion rate
96	      supabase.from("profiles").select("plan"),
97	      // Active users 7d / 30d (always absolute, not range-dependent)
98	      supabase.from("usage_logs").select("user_id").gte("created_at", sevenDaysAgo),
99	      supabase.from("usage_logs").select("user_id").gte("created_at", thirtyDaysAgo),
100	      // Resumes processed today/week/month (always absolute)
101	      supabase.from("resumes").select("id", { count: "exact", head: true }).gte("created_at", todayStart),
102	      supabase.from("resumes").select("id", { count: "exact", head: true }).gte("created_at", weekStart),
103	      supabase.from("resumes").select("id", { count: "exact", head: true }).gte("created_at", thirtyDaysAgo),
104	    ]);
105	
106	    const allUsers = usersRes.data?.users ?? [];
107	    const totalUsers = allUsers.length;
108	    const totalJobs = jobsRes.count ?? 0;
109	    const totalResumes = resumesRes.count ?? 0;
110	    const totalCreditsUsed = creditsRes.data?.reduce((sum: number, l: any) => sum + (l.credits_used || 0), 0) ?? 0;
111	
112	    // Revenue
113	    const totalRevenue = paidPaymentsAllRes.data?.reduce((sum: number, p: any) => sum + (p.amount || 0), 0) ?? 0;
114	    const mrrRange = paidPaymentsRangeRes.data?.reduce((sum: number, p: any) => sum + (p.amount || 0), 0) ?? 0;
115	
116	    // Conversion rate
117	    const profiles = profilesRes.data ?? [];
118	    const paidUsers = profiles.filter((p: any) => p.plan && p.plan !== "free").length;
119	    const conversionRate = totalUsers > 0 ? Math.round((paidUsers / totalUsers) * 100) : 0;
120	
121	    // Active users
122	    const activeUsers7d = new Set(usage7dRes.data?.map((l: any) => l.user_id) ?? []).size;
123	    const activeUsers30d = new Set(usage30dRes.data?.map((l: any) => l.user_id) ?? []).size;
124	
125	    // Avg resumes per job
126	    const avgResumesPerJob = totalJobs > 0 ? Math.round((totalResumes / totalJobs) * 10) / 10 : 0;
127	
128	    // Resumes processed
129	    const resumesToday = resumesTodayRes.count ?? 0;
130	    const resumesWeek = resumesWeekRes.count ?? 0;
131	    const resumesMonth = resumesMonthRes.count ?? 0;
132	
133	    // Daily chart aggregation — build day-by-day map for the range
134	    const totalRangeDays = Math.ceil((rangeEndDate.getTime() - rangeStartDate.getTime()) / (24 * 60 * 60 * 1000)) + 1;
135	    const dailyMap: Record<string, { credits: number; jobs: number; signups: number; revenue: number; active_users: number }> = {};
136	    for (let i = totalRangeDays - 1; i >= 0; i--) {
137	      const d = new Date(rangeEndDate.getTime() - i * 24 * 60 * 60 * 1000);
138	      const key = d.toISOString().slice(0, 10);
139	      dailyMap[key] = { credits: 0, jobs: 0, signups: 0, revenue: 0, active_users: 0 };
140	    }
141	
142	    const dailyActiveUsers: Record<string, Set<string>> = {};
143	    dailyUsageRes.data?.forEach((l: any) => {
144	      const key = l.created_at.slice(0, 10);
145	      if (dailyMap[key]) {
146	        dailyMap[key].credits += l.credits_used || 0;
147	        if (!dailyActiveUsers[key]) dailyActiveUsers[key] = new Set();
148	        dailyActiveUsers[key].add(l.user_id);
149	      }
150	    });
151	    Object.entries(dailyActiveUsers).forEach(([key, set]) => {
152	      if (dailyMap[key]) dailyMap[key].active_users = set.size;
153	    });
154	    dailyJobsRes.data?.forEach((j: any) => {
155	      const key = j.created_at.slice(0, 10);
156	      if (dailyMap[key]) dailyMap[key].jobs += 1;
157	    });
158	    allUsers.forEach((u: any) => {
159	      const key = u.created_at?.slice(0, 10);
160	      if (key && dailyMap[key]) dailyMap[key].signups += 1;
161	    });
162	    paidPaymentsRangeRes.data?.forEach((p: any) => {
163	      const key = p.created_at.slice(0, 10);
164	      if (dailyMap[key]) dailyMap[key].revenue += p.amount || 0;
165	    });
166	    const daily_chart = Object.entries(dailyMap).map(([date, v]) => ({ date, ...v }));
167	
168	    return new Response(JSON.stringify({
169	      total_users: totalUsers,
170	      total_jobs: totalJobs,
171	      total_resumes: totalResumes,
172	      total_credits_used: totalCreditsUsed,
173	      total_revenue: totalRevenue,
174	      mrr_30d: mrrRange,
175	      conversion_rate: conversionRate,
176	      active_users_7d: activeUsers7d,
177	      active_users_30d: activeUsers30d,
178	      avg_resumes_per_job: avgResumesPerJob,
179	      resumes_today: resumesToday,
180	      resumes_week: resumesWeek,
181	      resumes_month: resumesMonth,
182	      daily_chart,
183	    }), { headers: { ...cors, "Content-Type": "application/json" } });
184	  } catch (err: unknown) {
185	    return new Response(JSON.stringify({ error: err instanceof Error ? err.message : String(err) }), {
186	      status: 500, headers: { ...cors, "Content-Type": "application/json" },
187	    });
188	  }
189	});
