1	import { serve } from "https://deno.land/std@0.168.0/http/server.ts";
2	import { createClient } from "https://esm.sh/@supabase/supabase-js@2.49.2";
3	import { logSystemError, errorToMessage, errorToStack } from "../_shared/logError.ts";
4	import { corsHeaders, handlePreflight } from "../_shared/cors.ts";
5	
6	async function authenticateAdmin(req: Request) {
7	  const SUPABASE_URL = Deno.env.get("SUPABASE_URL")!;
8	  const SUPABASE_SERVICE_ROLE_KEY = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!;
9	  const anonKey = Deno.env.get("SUPABASE_ANON_KEY")!;
10	
11	  const authHeader = req.headers.get("Authorization");
12	  if (!authHeader?.startsWith("Bearer ")) throw new Error("No auth");
13	
14	  const supabaseUser = createClient(SUPABASE_URL, anonKey, {
15	    global: { headers: { Authorization: authHeader } },
16	  });
17	  const { data: { user }, error: userError } = await supabaseUser.auth.getUser();
18	  if (userError || !user) throw new Error("Unauthorized");
19	  const adminUserId = user.id;
20	
21	  const supabase = createClient(SUPABASE_URL, SUPABASE_SERVICE_ROLE_KEY);
22	
23	  const { data: roles } = await supabase.from("user_roles").select("role").eq("user_id", adminUserId);
24	  if (!roles?.some((r: any) => r.role === "admin")) {
25	    throw new Error("Admin access required");
26	  }
27	
28	  return { supabase, adminUserId };
29	}
30	
31	serve(async (req) => {
32	  const cors = corsHeaders(req);
33	
34	  const preflight = handlePreflight(req);
35	  if (preflight) return preflight;
36	
37	  try {
38	    const { supabase, adminUserId } = await authenticateAdmin(req);
39	
40	    let body: any = null;
41	    try {
42	      const text = await req.text();
43	      if (text) body = JSON.parse(text);
44	    } catch {
45	      // empty or invalid body — treat as list request
46	    }
47	
48	    const action = body?.action;
49	
50	    // ─── Ban / Suspend user ───
51	    if (action === "ban") {
52	      const { user_id, banned } = body;
53	      if (!user_id) throw new Error("user_id required");
54	      if (banned) {
55	        const { error } = await supabase.auth.admin.updateUserById(user_id, { ban_duration: "876000h" }); // ~100 years
56	        if (error) throw error;
57	      } else {
58	        const { error } = await supabase.auth.admin.updateUserById(user_id, { ban_duration: "none" });
59	        if (error) throw error;
60	      }
61	      return new Response(JSON.stringify({ success: true }), {
62	        headers: { ...cors, "Content-Type": "application/json" },
63	      });
64	    }
65	
66	    // ─── Get user activity detail ───
67	    if (action === "activity") {
68	      const { user_id } = body;
69	      if (!user_id) throw new Error("user_id required");
70	
71	      const [usageRes, jobsRes, resumesRes, paymentsRes] = await Promise.all([
72	        supabase.from("usage_logs").select("*").eq("user_id", user_id).order("created_at", { ascending: false }).limit(50),
73	        supabase.from("jobs").select("id, title, status, created_at").eq("user_id", user_id).order("created_at", { ascending: false }).limit(50),
74	        supabase.from("resumes").select("id, filename, status, created_at, job_id").order("created_at", { ascending: false }).limit(100),
75	        supabase.from("payments").select("id, amount, currency, status, credits_purchased, created_at").eq("user_id", user_id).order("created_at", { ascending: false }).limit(50),
76	      ]);
77	
78	      // Filter resumes to only those belonging to user's jobs
79	      const jobIds = new Set(jobsRes.data?.map((j: any) => j.id) ?? []);
80	      const userResumes = resumesRes.data?.filter((r: any) => jobIds.has(r.job_id)) ?? [];
81	
82	      return new Response(JSON.stringify({
83	        usage_logs: usageRes.data ?? [],
84	        jobs: jobsRes.data ?? [],
85	        resumes: userResumes,
86	        payments: paymentsRes.data ?? [],
87	      }), { headers: { ...cors, "Content-Type": "application/json" } });
88	    }
89	
90	    // ─── GDPR data export ───
91	    if (action === "gdpr_export") {
92	      const { user_id } = body;
93	      if (!user_id) throw new Error("user_id required");
94	
95	      const { data: authUser } = await supabase.auth.admin.getUserById(user_id);
96	      const [profileRes, usageRes, jobsRes, paymentsRes, rolesRes] = await Promise.all([
97	        supabase.from("profiles").select("*").eq("user_id", user_id),
98	        supabase.from("usage_logs").select("*").eq("user_id", user_id),
99	        supabase.from("jobs").select("*").eq("user_id", user_id),
100	        supabase.from("payments").select("*").eq("user_id", user_id),
101	        supabase.from("user_roles").select("*").eq("user_id", user_id),
102	      ]);
103	
104	      // Get resumes for user's jobs
105	      const jobIds = jobsRes.data?.map((j: any) => j.id) ?? [];
106	      let resumes: any[] = [];
107	      if (jobIds.length > 0) {
108	        const { data } = await supabase.from("resumes").select("id, filename, status, created_at, candidate_name, source").in("job_id", jobIds);
109	        resumes = data ?? [];
110	      }
111	
112	      const exportData = {
113	        exported_at: new Date().toISOString(),
114	        user: {
115	          id: authUser?.user?.id,
116	          email: authUser?.user?.email,
117	          created_at: authUser?.user?.created_at,
118	          last_sign_in_at: authUser?.user?.last_sign_in_at,
119	        },
120	        profile: profileRes.data?.[0] ?? null,
121	        roles: rolesRes.data ?? [],
122	        jobs: jobsRes.data ?? [],
123	        resumes,
124	        usage_logs: usageRes.data ?? [],
125	        payments: paymentsRes.data ?? [],
126	      };
127	
128	      return new Response(JSON.stringify(exportData), {
129	        headers: { ...cors, "Content-Type": "application/json" },
130	      });
131	    }
132	
133	    // ─── Update user profile (existing) ───
134	    if (body && body.user_id && !action) {
135	      const { user_id, credits, plan, email_enabled, bonus_credits, subscription_credits, topup_credits } = body;
136	
137	      // Get current profile to detect bonus credit increase
138	      const { data: currentProfile } = await supabase
139	        .from("profiles")
140	        .select("bonus_credits")
141	        .eq("user_id", user_id)
142	        .single();
143	      const oldBonus = currentProfile?.bonus_credits ?? 0;
144	
145	      const updates: any = {};
146	      if (credits !== undefined) updates.credits = credits;
147	      if (plan !== undefined) updates.plan = plan;
148	      if (email_enabled !== undefined) updates.email_enabled = email_enabled;
149	      if (bonus_credits !== undefined) updates.bonus_credits = Math.max(0, bonus_credits);
150	      if (subscription_credits !== undefined) updates.subscription_credits = Math.max(0, subscription_credits);
151	      if (topup_credits !== undefined) updates.topup_credits = Math.max(0, topup_credits);
152	
153	      const { error } = await supabase.from("profiles").update(updates).eq("user_id", user_id);
154	      if (error) throw error;
155	
156	      // Send email notification if bonus credits were increased
157	      const newBonus = bonus_credits !== undefined ? Math.max(0, bonus_credits) : oldBonus;
158	      if (newBonus > oldBonus) {
159	        const added = newBonus - oldBonus;
160	        try {
161	          // Get user email from auth
162	          const { data: { user: targetUser } } = await supabase.auth.admin.getUserById(user_id);
163	          if (targetUser?.email) {
164	            await supabase.functions.invoke("send-email", {
165	              body: {
166	                to: targetUser.email,
167	                template_key: "bonus_credits_received",
168	                variables: {
169	                  user_name: targetUser.email.split("@")[0],
170	                  credits_added: String(added),
171	                  total_bonus: String(newBonus),
172	                  app_url: Deno.env.get("APP_URL") || "https://rankora.co",
173	                },
174	              },
175	            });
176	          }
177	        } catch (emailErr) {
178	          console.error("Failed to send bonus credit email:", emailErr);
179	          await logSystemError({
180	            function_name: "admin-users",
181	            error_type: "BONUS_CREDIT_EMAIL_FAILED",
182	            severity: "warning",
183	            error_message: errorToMessage(emailErr),
184	            error_stack: errorToStack(emailErr),
185	            user_id: user_id,
186	            context_json: { credits_added: newBonus - oldBonus, total_bonus: newBonus },
187	          });
188	        }
189	      }
190	
191	      return new Response(JSON.stringify({ success: true }), {
192	        headers: { ...cors, "Content-Type": "application/json" },
193	      });
194	    }
195	
196	    // ─── Regenerate user inbox email ───
197	    if (action === "regenerate_inbox") {
198	      const { user_id } = body;
199	      if (!user_id) throw new Error("user_id required");
200	
201	      const { data, error } = await supabase.rpc("generate_user_inbox_email", { p_user_id: user_id });
202	      if (error) throw error;
203	
204	      return new Response(JSON.stringify({ success: true, inbox_email: data }), {
205	        headers: { ...cors, "Content-Type": "application/json" },
206	      });
207	    }
208	
