256	          if (allowedFields.includes(key)) cleanUpdates[key] = val;
257	        }
258	
259	        const { error: updateErr } = await supabase.from("platform_config").update(cleanUpdates).eq("id", configRow.id);
260	        if (updateErr) throw updateErr;
