72	      console.error("[useAuth] Error fetching profile:", err);
73	      setAuthError(
74	        err instanceof Error
75	          ? `Could not load profile: ${err.message}`
76	          : "Could not load profile",
77	      );
78	    }
79	  };
80	
81	  const fetchRole = async (userId: string) => {
82	    try {
83	      const { data, error } = await supabase
84	        .from("user_roles")
85	        .select("role")
86	        .eq("user_id", userId);
87	      if (error) throw error;
88	      setIsAdmin(
89	        (data ?? []).some((r: { role: string }) => r.role === "admin"),
90	      );
91	    } catch (err) {
92	      console.error("[useAuth] Error fetching role:", err);
93	      // Role fetch failures should NOT silently leave isAdmin=false from
94	      // a previous session — reset it and surface the error so the admin
95	      // panel redirect doesn't look like a bug to the user.
96	      setIsAdmin(false);
97	      setAuthError(
98	        err instanceof Error
99	          ? `Could not verify permissions: ${err.message}`
100	          : "Could not verify permissions",
101	      );
102	    }
103	  };
104	
105	  const refreshProfile = async () => {
106	    if (userIdRef.current) await fetchProfile(userIdRef.current);
107	  };
108	
109	  useEffect(() => {
110	    // Single source of truth: onAuthStateChange fires an INITIAL_SESSION
111	    // event on subscribe, which gives us the current session without a
112	    // separate getSession() call. This eliminates the race where
113	    // getSession() could resolve with null before onAuthStateChange
114	    // caught up, briefly wiping a known-good user state.
115	    const {
116	      data: { subscription },
117	    } = supabase.auth.onAuthStateChange(async (_event, nextSession) => {
118	      setSession(nextSession);
119	      setUser(nextSession?.user ?? null);
120	      userIdRef.current = nextSession?.user?.id ?? null;
121	
122	      if (nextSession?.user) {
123	        // setTimeout avoids the Supabase deadlock inside onAuthStateChange
124	        setTimeout(async () => {
125	          await Promise.all([
126	            fetchProfile(nextSession.user.id),
127	            fetchRole(nextSession.user.id),
128	          ]);
129	        }, 0);
130	      } else {
131	        setProfile(null);
132	        setIsAdmin(false);
133	        setAuthError(null);
134	      }
135	      setLoading(false);
136	    });
137	
138	    return () => subscription.unsubscribe();
139	  }, []);
140	
141	  // Refresh profile on window focus + every 2min to keep credits current
142	  useEffect(() => {
143	    if (!user) return;
144	    const handleFocus = () => fetchProfile(user.id);
145	    window.addEventListener("focus", handleFocus);
146	    const interval = setInterval(() => fetchProfile(user.id), 120_000);
147	    return () => {
148	      window.removeEventListener("focus", handleFocus);
149	      clearInterval(interval);
150	    };
151	    // Intentional: re-run only on user identity change (id), not on every
152	    // Supabase user object reference change. fetchProfile is stable because
153	    // it closes over `supabase` which is a module singleton.
154	    // eslint-disable-next-line react-hooks/exhaustive-deps
155	  }, [user?.id]);
156	
157	  const signOut = async () => {
158	    await supabase.auth.signOut();
159	    setUser(null);
160	    setSession(null);
161	    setProfile(null);
162	    setIsAdmin(false);
163	    setAuthError(null);
164	    // Full page reload to /auth — clears all cached React state,
165	    // query cache, and Supabase tokens. router.replace() would leave
166	    // stale client components rendered for a frame.
167	    window.location.href = "/auth";
168	  };
169	
170	  return (
171	    <AuthContext.Provider
172	      value={{
173	        user,
174	        session,
175	        loading,
176	        isAdmin,
177	        profile,
178	        authError,
179	        signOut,
180	        refreshProfile,
181	      }}
182	    >
183	      {children}
184	    </AuthContext.Provider>
185	  );
186	}
