1	/**
2	 * Shared CORS configuration for all edge functions.
3	 *
4	 * Origins are resolved at boot from environment variables:
5	 *   APP_URL              — primary app URL (e.g. https://rankora-develop.up.railway.app)
6	 *   EXTRA_ALLOWED_ORIGINS — comma-separated additional origins (optional)
7	 *
8	 * Default origins (always included): rankora.co, www.rankora.co,
9	 * localhost:8080, localhost:5173.
10	 *
11	 * To add a new origin without redeploying functions:
12	 *   supabase secrets set EXTRA_ALLOWED_ORIGINS="https://new-domain.com,https://other.com"
13	 *   supabase functions deploy <function-name>
14	 */
15	
16	const DEFAULT_ORIGINS = [
17	  "https://rankora.co",
18	  "https://www.rankora.co",
19	  "http://localhost:8080",
20	  "http://localhost:5173",
21	];
22	
23	function buildAllowedOrigins(): Set<string> {
24	  const origins = new Set(DEFAULT_ORIGINS);
25	
26	  // Primary app URL — always first priority
27	  const appUrl = Deno.env.get("APP_URL");
28	  if (appUrl) origins.add(appUrl.replace(/\/$/, ""));
29	
30	  // Extra origins — comma-separated, for staging/preview/custom domains
31	  const extra = Deno.env.get("EXTRA_ALLOWED_ORIGINS");
32	  if (extra) {
33	    for (const raw of extra.split(",")) {
34	      const trimmed = raw.trim().replace(/\/$/, "");
35	      if (trimmed) origins.add(trimmed);
36	    }
37	  }
38	
39	  return origins;
40	}
41	
42	const ALLOWED_ORIGINS = buildAllowedOrigins();
43	const FALLBACK_ORIGIN = Deno.env.get("APP_URL") || "https://rankora.co";
44	
45	/**
46	 * Returns the origin to use in Access-Control-Allow-Origin.
47	 * If the request origin is in our allow-list, reflect it back.
48	 * Otherwise, return the primary APP_URL.
49	 */
50	export function getCorsOrigin(req: Request): string {
51	  const origin = req.headers.get("origin") || "";
52	  return ALLOWED_ORIGINS.has(origin) ? origin : FALLBACK_ORIGIN;
53	}
54	
55	/** Standard CORS headers for most edge functions. */
56	export function corsHeaders(req: Request): Record<string, string> {
57	  return {
58	    "Access-Control-Allow-Origin": getCorsOrigin(req),
59	    "Access-Control-Allow-Headers":
60	      "authorization, x-client-info, apikey, content-type, x-supabase-client-platform, x-supabase-client-platform-version, x-supabase-client-runtime, x-supabase-client-runtime-version",
61	  };
62	}
63	
64	/** Handle preflight OPTIONS request. */
65	export function handlePreflight(req: Request): Response | null {
66	  if (req.method === "OPTIONS") {
67	    return new Response(null, { headers: corsHeaders(req) });
68	  }
69	  return null;
70	}
